    public static Sprite Get道纹Sprite(道纹Type type, QualityType qualityType)
    {
        switch (type)
        {
            case 道纹Type.增加百分比攻击力:
                switch ((int)qualityType)
                {
                    case 4: return 锋锐4;
                    case 5: return 锋锐5;
                    case 6: return 锋锐6;
                    case 7: return 锋锐7;
                    case 8: return 锋锐8;
                }

                break;

            case 道纹Type.增加战士伤害:
                switch ((int)qualityType)
                {
                    case 4: return 战意4;
                    case 5: return 战意5;
                    case 6: return 战意6;
                    case 7: return 战意7;
                    case 8: return 战意8;
                }

                break;

            case 道纹Type.增加法师伤害:
                switch ((int)qualityType)
                {
                    case 4: return 咒力4;
                    case 5: return 咒力5;
                    case 6: return 咒力6;
                    case 7: return 咒力7;
                    case 8: return 咒力8;
                }

                break;

            case 道纹Type.增加控制伤害:
                switch ((int)qualityType)
                {
                    case 4: return 束魂4;
                    case 5: return 束魂5;
                    case 6: return 束魂6;
                    case 7: return 束魂7;
                    case 8: return 束魂8;
