                {
                    case 4: return 镇关4;
                    case 5: return 镇关5;
                    case 6: return 镇关6;
                    case 7: return 镇关7;
                    case 8: return 镇关8;
                }

                break;

            case 道纹Type.射手对远距离敌人伤害增高:
                switch ((int)qualityType)
                {
                    case 4: return 连珠4;
                    case 5: return 连珠5;
                    case 6: return 连珠6;
                    case 7: return 连珠7;
                    case 8: return 连珠8;
                }

                break;

            case 道纹Type.控制冷却缩减:
                switch ((int)qualityType)
                {
                    case 4: return 回响4;
                    case 5: return 回响5;
                    case 6: return 回响6;
                    case 7: return 回响7;
                    case 8: return 回响8;
                }

                break;

            case 道纹Type.法师暴击率:
                switch ((int)qualityType)
                {
                    case 4: return 心炎4;
                    case 5: return 心炎5;
                    case 6: return 心炎6;
                    case 7: return 心炎7;
                    case 8: return 心炎8;
                }

                break;

            case 道纹Type.辅助被辅助英雄伤害增幅:
                switch ((int)qualityType)
                {
                    case 4: return 扶摇4;
                    case 5: return 扶摇5;
                    case 6: return 扶摇6;
                    case 7: return 扶摇7;
                    case 8: return 扶摇8;
                }

                break;

            case 道纹Type.三味真火无视抗性百分比:
                switch ((int)qualityType)
                {
                    case 4: return 焚天4;
                    case 5: return 焚天5;
                    case 6: return 焚天6;
                    case 7: return 焚天7;
                    case 8: return 焚天8;
                }

                break;

            case 道纹Type.孙悟空每秒增加伤害:
                switch ((int)qualityType)
                {
                    case 4: return 齐天战意4;
                    case 5: return 齐天战意5;
                    case 6: return 齐天战意6;
                    case 7: return 齐天战意7;
                    case 8: return 齐天战意8;
                }

                break;

            case 道纹Type.碧霄冰龙有概率再次释放:
                switch ((int)qualityType)
                {
                    case 4: return 冰龙回响4;
                    case 5: return 冰龙回响5;
                    case 6: return 冰龙回响6;
                    case 7: return 冰龙回响7;
                    case 8: return 冰龙回响8;
                }

                break;

            case 道纹Type.琼霄定身衰减效果减少:
                switch ((int)qualityType)
                {
                    case 4: return 定身4;
                    case 5: return 定身5;
                    case 6: return 定身6;
                    case 7: return 定身7;
                    case 8: return 定身8;
                }

                break;

            case 道纹Type.云霄最终伤害:
                switch ((int)qualityType)
                {
                    case 4: return 云破4;
                    case 5: return 云破5;
                    case 6: return 云破6;
                    case 7: return 云破7;
                    case 8: return 云破8;
                }

                break;

            case 道纹Type.后羿距离越远伤害越高:
                switch ((int)qualityType)
                {
                    case 4: return 落日4;
                    case 5: return 落日5;
                    case 6: return 落日6;
                    case 7: return 落日7;
                    case 8: return 落日8;
                }

                break;

            case 道纹Type.羲和灼烧伤害:
                switch ((int)qualityType)
                {
                    case 4: return 曦日灼4;
                    case 5: return 曦日灼5;
                    case 6: return 曦日灼6;
                    case 7: return 曦日灼7;
                    case 8: return 曦日灼8;
                }

                break;

            case 道纹Type.常曦有概率冻结敌人:
                switch ((int)qualityType)
                {
                    case 4: return 寒月4;
                    case 5: return 寒月5;
                    case 6: return 寒月6;
                    case 7: return 寒月7;
                    case 8: return 寒月8;
                }

                break;

            case 道纹Type.女娲增加被辅助冷却缩减:
                switch ((int)qualityType)
                {
                    case 4: return 补天4;
                    case 5: return 补天5;
                    case 6: return 补天6;
                    case 7: return 补天7;
