                    case 5: return 截天5;
                    case 6: return 截天6;
                    case 7: return 截天7;
                    case 8: return 截天8;
                }

                break;

            case 道纹Type.老子旋风体积越大伤害越高:
                switch ((int)qualityType)
                {
                    case 4: return 玄风4;
                    case 5: return 玄风5;
                    case 6: return 玄风6;
                    case 7: return 玄风7;
                    case 8: return 玄风8;
                }

                break;

            case 道纹Type.元始每次释放有概率增加火种数量:
                switch ((int)qualityType)
                {
                    case 4: return 始火4;
                    case 5: return 始火5;
                    case 6: return 始火6;
                    case 7: return 始火7;
                    case 8: return 始火8;
                }

                break;

            case 道纹Type.鸿钧每释放陨石增加伤害:
                switch ((int)qualityType)
                {
                    case 4: return 鸿蒙陨4;
                    case 5: return 鸿蒙陨5;
                    case 6: return 鸿蒙陨6;
                    case 7: return 鸿蒙陨7;
