                }

                break;

            case 道纹Type.盘古每击杀敌人增加伤害:
                switch ((int)qualityType)
                {
                    case 4: return 开天4;
                    case 5: return 开天5;
                    case 6: return 开天6;
                    case 7: return 开天7;
                    case 8: return 开天8;
                }

                break;
        }

        return null;
    }

