    public static Sprite GetBuffIcon(丹药Type type, QualityType qualityType)
    {
        switch (type)
        {
            case 丹药Type.修炼速度:
                switch (qualityType)
                {
                    case QualityType.黄品:
                        return Buff修炼速度白;
                    case QualityType.玄品:
                        return Buff修炼速度绿;
                    case QualityType.地品:
                        return Buff修炼速度蓝;
                    case QualityType.天品:
                        return Buff修炼速度紫;
                    case QualityType.宇品:
                        return Buff修炼速度橙;
                    case QualityType.宙品:
                        return Buff修炼速度粉;
                    case QualityType.洪品:
                        return Buff修炼速度红;
                    case QualityType.荒品:
                        return Buff修炼速度彩;
                }
                break;
            
            case 丹药Type.掉宝率:
                switch (qualityType)
                {
                    case QualityType.黄品:
                        return Buff掉宝率白;
                    case QualityType.玄品:
                        return Buff掉宝率绿;
                    case QualityType.地品:
                        return Buff掉宝率蓝;
                    case QualityType.天品:
                        return Buff掉宝率紫;
                    case QualityType.宇品:
                        return Buff掉宝率橙;
                    case QualityType.宙品:
                        return Buff掉宝率粉;
                    case QualityType.洪品:
                        return Buff掉宝率红;
                    case QualityType.荒品:
                        return Buff掉宝率彩;
                }
                break;
        }

        return null;
    }

